func:
// Battery total charge/discharge
// 616-617: Total Batt Charge (0.1kWh, U32)
// 618-619: Total Batt Discharge (0.1kWh, U32)

msg.baseAddr = 616;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 616,
    quantity: 4
};
return msg;

// Grid total import/export
// 622-623: Total Grid Import (0.1kWh, U32)
// 624-625: Total Grid Export (0.1kWh, U32)

msg.baseAddr = 622;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 622,
    quantity: 4
};
return msg;

// Load total
// 627-628: Total Load (0.1kWh, U32)

msg.baseAddr = 627;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 627,
    quantity: 2
};
return msg;

// PV total
// 634-635: Total PV (0.1kWh, U32)

msg.baseAddr = 634;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 634,
    quantity: 2
};
return msg;

// Generator total
// 637-638: Total Gen (0.1kWh, U32)

msg.baseAddr = 637;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 637,
    quantity: 2
};
return msg;

// Build TotalEnergyFlowState from multiple Modbus reads.

let raw = msg.payload;
let data = raw;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

if (typeof raw === "string" || !Array.isArray(data)) {
    return null;
}

let baseAddr = msg.baseAddr;
if (typeof baseAddr !== "number") {
    baseAddr = (msg.modbusRequest && msg.modbusRequest.address);
}
if (typeof baseAddr !== "number") {
    node.warn("TotalEnergyFlowState: missing base address");
    return null;
}

// Helper: combine two 16-bit words to 32-bit unsigned
function u32(low, high) {
    return ((high & 0xFFFF) << 16) | (low & 0xFFFF);
}

// ---- Store partials ----

// Battery 616-619
if (baseAddr === 616) {
    const chargeLow = data[0] || 0;      // 616
    const chargeHigh = data[1] || 0;     // 617
    const dischargeLow = data[2] || 0;   // 618
    const dischargeHigh = data[3] || 0;  // 619

    flow.set("tefs_part_battery", {
        totalChargeEnergyKWh: Math.round(u32(chargeLow, chargeHigh) * 0.1 * 10) / 10,
        totalDischargeEnergyKWh: Math.round(u32(dischargeLow, dischargeHigh) * 0.1 * 10) / 10
    });
}

// Grid 622-625
else if (baseAddr === 622) {
    const importLow = data[0] || 0;    // 622
    const importHigh = data[1] || 0;   // 623
    const exportLow = data[2] || 0;    // 624
    const exportHigh = data[3] || 0;   // 625

    flow.set("tefs_part_grid", {
        importTotalEnergyKWh: Math.round(u32(importLow, importHigh) * 0.1 * 10) / 10,
        exportTotalEnergyKWh: Math.round(u32(exportLow, exportHigh) * 0.1 * 10) / 10
    });
}

// Load 627-628
else if (baseAddr === 627) {
    const loadLow = data[0] || 0;   // 627
    const loadHigh = data[1] || 0;  // 628

    flow.set("tefs_part_load", {
        totalEnergyKWh: Math.round(u32(loadLow, loadHigh) * 0.1 * 10) / 10
    });
}

// PV 634-635
else if (baseAddr === 634) {
    const pvLow = data[0] || 0;    // 634
    const pvHigh = data[1] || 0;   // 635

    flow.set("tefs_part_pv", {
        totalEnergyKWh: Math.round(u32(pvLow, pvHigh) * 0.1 * 10) / 10
    });
}

// Generator 637-638
else if (baseAddr === 637) {
    const genLow = data[0] || 0;    // 637
    const genHigh = data[1] || 0;   // 638

    flow.set("tefs_part_gen", {
        totalEnergyKWh: Math.round(u32(genLow, genHigh) * 0.1 * 10) / 10
    });
}
else {
    return null;
}

// ---- Try to assemble ----

const batteryPart = flow.get("tefs_part_battery");
const gridPart = flow.get("tefs_part_grid");
const loadPart = flow.get("tefs_part_load");
const pvPart = flow.get("tefs_part_pv");
const genPart = flow.get("tefs_part_gen");

if (!batteryPart || !gridPart || !loadPart || !pvPart || !genPart) {
    return null;
}

const deviceId = msg.deviceId
    || global.get("DEVICE_ID")
    || env.get("DEVICE_ID")
    || "EC100";

const state = {
    kind: "TotalEnergyFlowState",
    timestampUtc: new Date().toISOString(),
    version: 1,
    deviceId: deviceId,

    grid: {
        importTotalEnergyKWh: gridPart.importTotalEnergyKWh,
        exportTotalEnergyKWh: gridPart.exportTotalEnergyKWh
    },

    pv: {
        totalEnergyKWh: pvPart.totalEnergyKWh,
        mppt: [
            { id: 1, totalEnergyKWh: null },
            { id: 2, totalEnergyKWh: null },
            { id: 3, totalEnergyKWh: null },
            { id: 4, totalEnergyKWh: null }
        ]
    },

    load: {
        totalEnergyKWh: loadPart.totalEnergyKWh
    },

    battery: {
        totalChargeEnergyKWh: batteryPart.totalChargeEnergyKWh,
        totalDischargeEnergyKWh: batteryPart.totalDischargeEnergyKWh
    },

    generator: {
        totalEnergyKWh: genPart.totalEnergyKWh
    }
};

// Clear partials
flow.set("tefs_part_battery", null);
flow.set("tefs_part_grid", null);
flow.set("tefs_part_load", null);
flow.set("tefs_part_pv", null);
flow.set("tefs_part_gen", null);

flow.set("totalEnergyFlowStateSnapshot", state);

msg.payload = state;
msg.state = state;
return msg;
